mapper.select:
select r.id, r.refund_no, r.customer_id, c.name as customer_name, r.amount, r.refund_type,
       r.receive_name, r.receive_account, r.receive_bank, r.reason,
       r.status, r.auditor, au.user_name as auditor_name, r.audit_time, r.audit_remark,
       r.creator, cr.user_name as creator_name, r.create_time
from crm_customer_refund r
left join crm_customer c on r.customer_id = c.id
left join sys_user au on r.auditor = au.user_id
left join sys_user cr on r.creator = cr.user_id


        and r.refund_no like concat('%', #{refundNo}, '%')

     and r.customer_id = #{customerId}

        and c.name like concat('%', #{customerName}, '%')

     and r.status = #{status}

        and c.owner_user = #{params.ownerUser}


        and r.create_time >= #{params.beginTime}


        and r.create_time <= #{params.endTime}


order by r.id desc
